HTML_PAGE='<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>BiteRec – Transparent Food Recommendations</title>\n  <script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>\n  <style>\n    /* ── Design tokens ──────────────────────────────────── */\n    :root {\n      --green:   #2d7a4f;\n      --green-l: #e8f5ee;\n      --blue:    #1a6fb5;\n      --blue-l:  #e8f3fd;\n      --amber:   #d97706;\n      --amber-l: #fef3c7;\n      --red:     #b91c1c;\n      --red-l:   #fee2e2;\n      --gray-50: #f9fafb;\n      --gray-100:#f3f4f6;\n      --gray-200:#e5e7eb;\n      --gray-400:#9ca3af;\n      --gray-600:#4b5563;\n      --gray-800:#1f2937;\n      --white:   #ffffff;\n      --shadow:  0 2px 12px rgba(0,0,0,.09);\n      --radius:  14px;\n      --font: \'Segoe UI\', system-ui, -apple-system, sans-serif;\n    }\n\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      font-family: var(--font);\n      background: var(--gray-50);\n      color: var(--gray-800);\n      min-height: 100vh;\n    }\n\n    /* ── Header ─────────────────────────────────────────── */\n    header {\n      background: linear-gradient(135deg, #1a4d2e 0%, #2d7a4f 60%, #1a6fb5 100%);\n      color: white;\n      padding: 0 24px;\n    }\n    .header-inner {\n      max-width: 1100px;\n      margin: 0 auto;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 18px 0;\n    }\n    .logo { display: flex; align-items: center; gap: 10px; }\n    .logo-icon { font-size: 32px; }\n    .logo h1 { font-size: 24px; font-weight: 700; letter-spacing: -0.5px; }\n    .logo p { font-size: 12px; opacity: 0.8; margin-top: 1px; }\n    .header-badge {\n      background: rgba(255,255,255,0.15);\n      border: 1px solid rgba(255,255,255,0.3);\n      border-radius: 20px;\n      padding: 4px 12px;\n      font-size: 11px;\n      font-weight: 600;\n      letter-spacing: 0.5px;\n    }\n\n    /* ── Main layout ─────────────────────────────────────── */\n    main {\n      max-width: 1100px;\n      margin: 0 auto;\n      padding: 32px 24px 64px;\n    }\n\n    /* ── Search section ──────────────────────────────────── */\n    .search-section {\n      background: var(--white);\n      border-radius: var(--radius);\n      box-shadow: var(--shadow);\n      padding: 28px 32px;\n      margin-bottom: 24px;\n    }\n    .search-section h2 {\n      font-size: 18px; font-weight: 600; margin-bottom: 16px;\n      display: flex; align-items: center; gap: 8px;\n    }\n    .search-row {\n      display: flex; gap: 10px; margin-bottom: 20px;\n    }\n    .search-input {\n      flex: 1; padding: 12px 16px; border: 2px solid var(--gray-200);\n      border-radius: 10px; font-size: 15px; font-family: var(--font);\n      transition: border-color .2s;\n    }\n    .search-input:focus { outline: none; border-color: var(--green); }\n    .btn {\n      padding: 12px 22px; border: none; border-radius: 10px;\n      font-size: 14px; font-weight: 600; cursor: pointer;\n      transition: all .15s; display: flex; align-items: center; gap: 6px;\n    }\n    .btn-primary { background: var(--green); color: white; }\n    .btn-primary:hover { background: #235f3e; }\n    .btn-outline {\n      background: transparent; color: var(--gray-600);\n      border: 2px solid var(--gray-200);\n    }\n    .btn-outline:hover { background: var(--gray-100); }\n\n    /* ── Controls ────────────────────────────────────────── */\n    .controls-grid {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 20px;\n      margin-top: 4px;\n    }\n    .control-group label {\n      display: block; font-size: 13px; font-weight: 600;\n      color: var(--gray-600); margin-bottom: 8px;\n    }\n    .slider-wrapper {\n      display: flex; align-items: center; gap: 10px;\n    }\n    .slider-label { font-size: 12px; color: var(--gray-600); white-space: nowrap; }\n    input[type="range"] {\n      flex: 1; accent-color: var(--green); cursor: pointer;\n    }\n    .slider-value {\n      font-size: 13px; font-weight: 700;\n      background: var(--green-l); color: var(--green);\n      padding: 2px 8px; border-radius: 6px; min-width: 80px; text-align: center;\n    }\n\n    .allergen-input {\n      width: 100%; padding: 10px 14px; border: 2px solid var(--gray-200);\n      border-radius: 8px; font-size: 14px; font-family: var(--font);\n    }\n    .allergen-input:focus { outline: none; border-color: var(--amber); }\n\n    .filter-checks { display: flex; flex-wrap: wrap; gap: 8px; }\n    .filter-chip {\n      display: flex; align-items: center; gap: 5px;\n      padding: 5px 12px; border: 2px solid var(--gray-200);\n      border-radius: 20px; font-size: 12px; font-weight: 600;\n      cursor: pointer; transition: all .15s; background: white;\n      color: var(--gray-600);\n    }\n    .filter-chip input { display: none; }\n    .filter-chip:has(input:checked) {\n      border-color: var(--green); background: var(--green-l); color: var(--green);\n    }\n\n    /* ── Search results dropdown ─────────────────────────── */\n    .search-row { position: relative; }\n    .search-results {\n      position: absolute; top: calc(100% + 6px); left: 0; right: 80px; z-index: 100;\n      background: white; border-radius: 10px;\n      box-shadow: 0 8px 30px rgba(0,0,0,.15);\n      border: 1px solid var(--gray-200); max-height: 320px; overflow-y: auto;\n    }\n    .result-item {\n      display: flex; align-items: center; gap: 12px;\n      padding: 12px 16px; cursor: pointer; border-bottom: 1px solid var(--gray-100);\n      transition: background .1s;\n    }\n    .result-item:last-child { border-bottom: none; }\n    .result-item:hover { background: var(--gray-50); }\n    .result-name { font-size: 14px; font-weight: 600; }\n    .result-meta { font-size: 12px; color: var(--gray-400); margin-top: 1px; }\n    .result-grades { display: flex; gap: 5px; margin-left: auto; }\n\n    /* ── Nutriscore / Eco badges ─────────────────────────── */\n    .grade-badge {\n      width: 28px; height: 28px; border-radius: 6px;\n      display: flex; align-items: center; justify-content: center;\n      font-weight: 800; font-size: 12px; color: white;\n      flex-shrink: 0;\n    }\n    .grade-A, .grade-A-plus { background: #038141; }\n    .grade-B { background: #85BB2F; }\n    .grade-C { background: #FECB02; color: #333; }\n    .grade-D { background: #EE8100; }\n    .grade-E, .grade-F { background: #E63E11; }\n    .grade-unknown, .grade-N\\/A, .grade-\\? { background: #9ca3af; }\n\n    /* ── Recommendations ─────────────────────────────────── */\n    #results-section { display: none; }\n    .results-header {\n      display: flex; align-items: center; justify-content: space-between;\n      margin-bottom: 20px;\n    }\n    .results-header h2 { font-size: 20px; font-weight: 700; }\n    .searched-label {\n      font-size: 12px; color: var(--gray-400); margin-top: 2px;\n    }\n\n    .cards-grid {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 20px;\n    }\n\n    .product-card {\n      background: white; border-radius: var(--radius);\n      box-shadow: var(--shadow); overflow: hidden;\n      border: 2px solid transparent; transition: border-color .2s, transform .15s;\n      display: flex; flex-direction: column;\n    }\n    .product-card:hover { transform: translateY(-2px); }\n    .card-searched { border-color: var(--gray-200); }\n    .card-health { border-color: var(--blue); }\n    .card-eco { border-color: var(--green); }\n\n    .card-header {\n      padding: 14px 18px 10px; border-bottom: 1px solid var(--gray-100);\n      display: flex; align-items: flex-start; gap: 10px;\n    }\n    .card-header-icon { font-size: 20px; flex-shrink: 0; }\n    .card-type-label {\n      font-size: 10px; font-weight: 700; letter-spacing: 0.8px;\n      text-transform: uppercase; opacity: 0.7;\n    }\n    .card-type-health { color: var(--blue); }\n    .card-type-eco { color: var(--green); }\n    .card-type-searched { color: var(--gray-600); }\n    .card-name {\n      font-size: 15px; font-weight: 700; margin-top: 2px;\n      line-height: 1.3;\n    }\n    .card-brand { font-size: 12px; color: var(--gray-400); margin-top: 2px; }\n\n    .card-scores {\n      display: flex; gap: 8px; padding: 12px 18px;\n      background: var(--gray-50); border-bottom: 1px solid var(--gray-100);\n    }\n    .score-item {\n      display: flex; align-items: center; gap: 6px;\n    }\n    .score-item span { font-size: 11px; color: var(--gray-600); font-weight: 600; }\n\n    .card-nutrients {\n      padding: 12px 18px; display: grid;\n      grid-template-columns: repeat(3, 1fr); gap: 8px;\n      flex: 1;\n    }\n    .nutrient {\n      display: flex; flex-direction: column; align-items: center;\n      background: var(--gray-50); border-radius: 8px; padding: 8px 4px;\n    }\n    .nutrient-val { font-size: 15px; font-weight: 700; }\n    .nutrient-lbl { font-size: 10px; color: var(--gray-400); margin-top: 1px; }\n\n    .card-explanation {\n      margin: 0 18px 14px; padding: 10px 14px;\n      border-radius: 8px; font-size: 12px; line-height: 1.5;\n    }\n    .expl-health { background: var(--blue-l); color: #1a4a7a; }\n    .expl-eco { background: var(--green-l); color: #1a4a2e; }\n\n    .card-source {\n      padding: 8px 18px 12px;\n      display: flex; align-items: center; gap: 5px;\n      font-size: 11px; color: var(--gray-400);\n    }\n    .card-source a { color: var(--blue); text-decoration: none; font-weight: 600; }\n    .card-source a:hover { text-decoration: underline; }\n\n    /* ── Radar chart section ─────────────────────────────── */\n    .chart-section {\n      background: white; border-radius: var(--radius);\n      box-shadow: var(--shadow); padding: 28px 32px; margin-top: 24px;\n    }\n    .chart-section h3 {\n      font-size: 16px; font-weight: 700; margin-bottom: 20px;\n      display: flex; align-items: center; gap: 8px;\n    }\n    .chart-container { max-width: 480px; margin: 0 auto; }\n\n    /* ── Loading / Empty states ──────────────────────────── */\n    .loading {\n      text-align: center; padding: 32px; color: var(--gray-400);\n    }\n    .spinner {\n      width: 36px; height: 36px; border: 3px solid var(--gray-200);\n      border-top-color: var(--green); border-radius: 50%;\n      animation: spin .6s linear infinite; margin: 0 auto 12px;\n    }\n    @keyframes spin { to { transform: rotate(360deg); } }\n\n    .empty-state {\n      text-align: center; padding: 48px 24px; color: var(--gray-400);\n    }\n    .empty-state .icon { font-size: 48px; margin-bottom: 12px; }\n    .empty-state p { font-size: 15px; }\n\n    /* ── Hero intro ──────────────────────────────────────── */\n    .hero {\n      text-align: center; padding: 40px 24px 32px;\n    }\n    .hero h2 { font-size: 28px; font-weight: 800; color: var(--green); margin-bottom: 12px; }\n    .hero p { font-size: 15px; color: var(--gray-600); max-width: 560px; margin: 0 auto 8px; }\n    .hero-pills {\n      display: flex; flex-wrap: wrap; gap: 8px;\n      justify-content: center; margin-top: 16px;\n    }\n    .hero-pill {\n      background: white; border: 1px solid var(--gray-200); border-radius: 20px;\n      padding: 5px 14px; font-size: 12px; font-weight: 600; color: var(--gray-600);\n    }\n\n    .source-note {\n      text-align: center; margin-top: 32px; font-size: 12px; color: var(--gray-400);\n    }\n    .source-note a { color: var(--blue); }\n\n    /* ── Responsive ──────────────────────────────────────── */\n    @media (max-width: 720px) {\n      .cards-grid { grid-template-columns: 1fr; }\n      .controls-grid { grid-template-columns: 1fr; }\n      .search-row { flex-direction: column; }\n    }\n  </style>\n</head>\n<body>\n\n<header>\n  <div class="header-inner">\n    <div class="logo">\n      <span class="logo-icon">🥗</span>\n      <div>\n        <h1>BiteRec</h1>\n        <p>Transparent Multi-Objective Food Recommendations</p>\n      </div>\n    </div>\n    <span class="header-badge">Powered by Open Food Facts · XAI</span>\n  </div>\n</header>\n\n<main>\n\n  <!-- Hero -->\n  <div class="hero" id="hero">\n    <h2>Find a better bite 🌿</h2>\n    <p>Search any food product and instantly discover alternatives that are\n       <strong>better for your health</strong> or <strong>better for the planet</strong> —\n       with transparent, plain-language explanations.</p>\n    <div class="hero-pills">\n      <span class="hero-pill">⚡ No registration required</span>\n      <span class="hero-pill">🔍 Explainable AI</span>\n      <span class="hero-pill">🌍 Eco-metrics in real units</span>\n      <span class="hero-pill">🛡️ Allergen filters</span>\n    </div>\n  </div>\n\n  <!-- Search & Controls -->\n  <div class="search-section">\n    <h2>🔍 Search a product</h2>\n\n    <div class="search-row">\n      <input type="text" id="searchInput" class="search-input"\n             placeholder=\'e.g. "milk", "pasta", "granola"…\' autocomplete="off" />\n      <button class="btn btn-primary" onclick="doSearch()">\n        Search\n      </button>\n      <div id="searchResults" class="search-results" style="display:none"></div>\n    </div>\n\n    <div class="controls-grid">\n      <!-- Slider -->\n      <div class="control-group">\n        <label>⚖️ My priority: Health vs Ecology</label>\n        <div class="slider-wrapper">\n          <span class="slider-label">🌍 Eco</span>\n          <input type="range" id="prioritySlider" min="0" max="100" value="70"\n                 oninput="updateSlider(this.value)" />\n          <span class="slider-label">💚 Health</span>\n        </div>\n        <div style="text-align:center; margin-top:6px;">\n          <span class="slider-value" id="sliderLabel">70% Health / 30% Eco</span>\n        </div>\n      </div>\n\n      <!-- Allergens -->\n      <div class="control-group">\n        <label>🚫 Allergen filter (hard constraint)</label>\n        <input type="text" id="allergenInput" class="allergen-input"\n               placeholder=\'e.g. "nuts, gluten, milk"\' />\n        <div style="font-size:11px; color:var(--gray-400); margin-top:5px;">\n          Products with these allergens will never appear in recommendations.\n        </div>\n      </div>\n\n      <!-- Nutritional filters -->\n      <div class="control-group">\n        <label>🔧 Nutritional filters</label>\n        <div class="filter-checks">\n          <label class="filter-chip">\n            <input type="checkbox" id="f_protein"> 💪 High Protein (≥10g)\n          </label>\n          <label class="filter-chip">\n            <input type="checkbox" id="f_sugar"> 🍬 Low Sugar (≤5g)\n          </label>\n        </div>\n      </div>\n\n      <!-- Eco filters -->\n      <div class="control-group">\n        <label>♻️ Ecological filters</label>\n        <div class="filter-checks">\n          <label class="filter-chip">\n            <input type="checkbox" id="f_organic"> 🌱 Organic / Bio\n          </label>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Results section -->\n  <div id="results-section">\n    <div class="results-header">\n      <div>\n        <h2>Recommendations</h2>\n        <div class="searched-label" id="searchedLabel"></div>\n      </div>\n      <button class="btn btn-outline" onclick="clearResults()">✕ Clear</button>\n    </div>\n\n    <div id="cardsContainer" class="cards-grid"></div>\n\n    <!-- Radar chart -->\n    <div class="chart-section">\n      <h3>📊 Comparison across key dimensions</h3>\n      <div class="chart-container">\n        <canvas id="radarChart"></canvas>\n      </div>\n      <p style="font-size:11px; color:var(--gray-400); text-align:center; margin-top:12px;">\n        Scores are normalised 0–100. Nutri-Score: A=100, B=75, C=50, D=25, E=0.\n        Eco-Score: A+=100 … F=0. Nutrients scaled relative to typical daily reference values.\n      </p>\n    </div>\n\n    <div class="source-note">\n      Data source: <a href="https://world.openfoodfacts.org" target="_blank">Open Food Facts</a>\n      – Open database licensed under <a href="https://opendatacommons.org/licenses/odbl/" target="_blank">ODbL</a>.\n      Nutritional and ecological data are crowdsourced and may be incomplete.\n    </div>\n  </div>\n\n  <!-- Empty hero shown until first search -->\n  <div id="emptyState" class="empty-state">\n    <div class="icon">🥦</div>\n    <p>Enter a product name above to get started.</p>\n  </div>\n\n</main>\n\n<script>\n/* ── State ──────────────────────────────────────────────────────────────── */\nconst API = \'\';  // same-origin; change to \'http://localhost:8000\' if needed\nlet radarChartInstance = null;\nlet currentProductIdx = null;\nlet searchDebounce = null;\n\n/* ── Slider ─────────────────────────────────────────────────────────────── */\nfunction updateSlider(val) {\n  const h = parseInt(val);\n  const e = 100 - h;\n  document.getElementById(\'sliderLabel\').textContent = `${h}% Health / ${e}% Eco`;\n  if (currentProductIdx !== null) {\n    loadRecommendations(currentProductIdx);\n  }\n}\n\n/* ── Search ─────────────────────────────────────────────────────────────── */\nconst searchInput = document.getElementById(\'searchInput\');\n\nsearchInput.addEventListener(\'input\', () => {\n  clearTimeout(searchDebounce);\n  const q = searchInput.value.trim();\n  if (q.length < 2) { hideDropdown(); return; }\n  searchDebounce = setTimeout(() => fetchSearch(q), 300);\n});\n\nsearchInput.addEventListener(\'keydown\', e => {\n  if (e.key === \'Enter\') { doSearch(); }\n  if (e.key === \'Escape\') { hideDropdown(); }\n});\n\ndocument.addEventListener(\'click\', e => {\n  if (!e.target.closest(\'.search-row\')) hideDropdown();\n});\n\nasync function doSearch() {\n  const q = searchInput.value.trim();\n  if (!q) return;\n  fetchSearch(q);\n}\n\nasync function fetchSearch(q) {\n  try {\n    const res = await fetch(`${API}/api/search?q=${encodeURIComponent(q)}`);\n    const data = await res.json();\n    renderDropdown(data.results);\n  } catch (err) {\n    console.error(err);\n  }\n}\n\nfunction renderDropdown(results) {\n  const el = document.getElementById(\'searchResults\');\n  if (!results || results.length === 0) {\n    el.innerHTML = \'<div class="result-item"><div class="result-name" style="color:var(--gray-400)">No products found</div></div>\';\n    el.style.display = \'block\';\n    return;\n  }\n  el.innerHTML = results.map(r => `\n    <div class="result-item" onclick="selectProduct(${r.idx}, \'${escHtml(r.name)}\')">\n      <div style="flex:1">\n        <div class="result-name">${escHtml(r.name)}</div>\n        <div class="result-meta">${escHtml(r.brand || \'\')} ${r.category && r.category !== \'unknown\' ? \'· \' + escHtml(r.category) : \'\'}</div>\n      </div>\n      <div class="result-grades">\n        ${gradeHtml(r.nutriscore_grade, \'N\')}\n        ${gradeHtml(r.eco_grade, \'E\')}\n      </div>\n    </div>\n  `).join(\'\');\n  el.style.display = \'block\';\n}\n\nfunction hideDropdown() {\n  document.getElementById(\'searchResults\').style.display = \'none\';\n}\n\nfunction selectProduct(idx, name) {\n  hideDropdown();\n  searchInput.value = name;\n  currentProductIdx = idx;\n  loadRecommendations(idx);\n}\n\n/* ── Recommendations ─────────────────────────────────────────────────────── */\nasync function loadRecommendations(idx) {\n  showLoading();\n  const h = parseInt(document.getElementById(\'prioritySlider\').value) / 100;\n  const allergens = document.getElementById(\'allergenInput\').value;\n  const highProtein = document.getElementById(\'f_protein\').checked;\n  const lowSugar = document.getElementById(\'f_sugar\').checked;\n  const organic = document.getElementById(\'f_organic\').checked;\n\n  const params = new URLSearchParams({\n    health_weight: h.toFixed(2),\n    allergens,\n    high_protein: highProtein,\n    low_sugar: lowSugar,\n    organic,\n  });\n\n  try {\n    const res = await fetch(`${API}/api/recommend/${idx}?${params}`);\n    const data = await res.json();\n    renderResults(data);\n  } catch (err) {\n    document.getElementById(\'cardsContainer\').innerHTML =\n      \'<div class="empty-state"><p>⚠️ Error fetching recommendations. Is the server running?</p></div>\';\n    console.error(err);\n  }\n}\n\nfunction showLoading() {\n  document.getElementById(\'hero\').style.display = \'none\';\n  document.getElementById(\'emptyState\').style.display = \'none\';\n  document.getElementById(\'results-section\').style.display = \'block\';\n  document.getElementById(\'cardsContainer\').innerHTML =\n    \'<div class="loading" style="grid-column:1/-1"><div class="spinner"></div><p>Finding the best alternatives…</p></div>\';\n}\n\nfunction renderResults(data) {\n  const { searched, better_for_you, better_for_earth } = data;\n\n  document.getElementById(\'searchedLabel\').textContent =\n    `Showing alternatives for: ${searched.name}`;\n\n  const cards = [\n    buildCard(searched, \'searched\', null),\n    buildCard(better_for_you, \'health\', better_for_you.explanation),\n    buildCard(better_for_earth, \'eco\', better_for_earth.explanation),\n  ];\n  document.getElementById(\'cardsContainer\').innerHTML = cards.join(\'\');\n  buildRadar(searched, better_for_you, better_for_earth);\n}\n\nfunction buildCard(p, type, explanation) {\n  const typeLabels = {\n    searched: { label: \'Your product\', icon: \'📦\', cls: \'searched\' },\n    health:   { label: \'Better for You 💚\', icon: \'💪\', cls: \'health\' },\n    eco:      { label: \'Better for Earth 🌍\', icon: \'🌿\', cls: \'eco\' },\n  };\n  const t = typeLabels[type];\n\n  const explHtml = explanation\n    ? `<div class="card-explanation expl-${type === \'health\' ? \'health\' : \'eco\'}">\n        <strong>Why?</strong> ${escHtml(explanation)}\n       </div>`\n    : \'\';\n\n  const offLink = p.url\n    ? `<a href="${escHtml(p.url)}" target="_blank">View on Open Food Facts ↗</a>`\n    : \'Open Food Facts\';\n\n  return `\n    <div class="product-card card-${t.cls}">\n      <div class="card-header">\n        <span class="card-header-icon">${t.icon}</span>\n        <div style="flex:1">\n          <div class="card-type-label card-type-${t.cls}">${t.label}</div>\n          <div class="card-name">${escHtml(p.name)}</div>\n          ${p.brand ? `<div class="card-brand">${escHtml(p.brand)}</div>` : \'\'}\n        </div>\n      </div>\n      <div class="card-scores">\n        <div class="score-item">\n          ${gradeHtml(p.nutriscore_grade, \'N\')}\n          <span>Nutri-Score ${formatGrade(p.nutriscore_grade)}</span>\n        </div>\n        <div class="score-item" style="margin-left:10px">\n          ${gradeHtml(p.eco_grade, \'E\')}\n          <span>Eco ${formatGrade(p.eco_grade)}</span>\n        </div>\n      </div>\n      <div class="card-nutrients">\n        ${nutrientCell(p.energy_kcal, \'kcal\', \'Energy\')}\n        ${nutrientCell(p.proteins, \'g\', \'Protein\')}\n        ${nutrientCell(p.fat, \'g\', \'Fat\')}\n        ${nutrientCell(p.sugars, \'g\', \'Sugars\')}\n        ${nutrientCell(p.fiber, \'g\', \'Fibre\')}\n        ${nutrientCell(p.salt, \'g\', \'Salt\')}\n      </div>\n      ${explHtml}\n      <div class="card-source">\n        🔗 Source: ${offLink}\n      </div>\n    </div>\n  `;\n}\n\nfunction nutrientCell(val, unit, label) {\n  const display = val !== null && val !== undefined ? `${val}${unit}` : \'–\';\n  return `\n    <div class="nutrient">\n      <span class="nutrient-val">${display}</span>\n      <span class="nutrient-lbl">${label}</span>\n    </div>`;\n}\n\n/* ── Radar chart ─────────────────────────────────────────────────────────── */\nfunction buildRadar(searched, health, eco) {\n  if (radarChartInstance) radarChartInstance.destroy();\n\n  // Normalize nutrients to 0-100 scale (rough daily reference values)\n  const DRV = { energy_kcal: 2000, proteins: 50, fat: 70, sugars: 90, fiber: 25, health_score: 100, eco_score: 100 };\n  function norm(p, key) {\n    const v = p[key];\n    if (v === null || v === undefined) return 0;\n    return Math.min(100, (v / DRV[key]) * 100);\n  }\n\n  const labels = [\'Nutri-Score\', \'Eco-Score\', \'Protein\', \'Fibre\', \'Low Sugar\', \'Low Fat\'];\n\n  function toRadarData(p) {\n    return [\n      p.health_score,\n      p.eco_score,\n      Math.min(100, (p.proteins / 30) * 100),\n      Math.min(100, (p.fiber !== null ? p.fiber : 0) / 10 * 100),\n      Math.max(0, 100 - Math.min(100, (p.sugars / 50) * 100)),\n      Math.max(0, 100 - Math.min(100, (p.fat / 70) * 100)),\n    ].map(v => Math.round(v));\n  }\n\n  const ctx = document.getElementById(\'radarChart\').getContext(\'2d\');\n  radarChartInstance = new Chart(ctx, {\n    type: \'radar\',\n    data: {\n      labels,\n      datasets: [\n        {\n          label: `${searched.name.slice(0,20)}…` ,\n          data: toRadarData(searched),\n          backgroundColor: \'rgba(156,163,175,0.2)\',\n          borderColor: \'#9ca3af\',\n          pointBackgroundColor: \'#9ca3af\',\n          borderWidth: 2,\n          pointRadius: 4,\n        },\n        {\n          label: \'Better for You 💚\',\n          data: toRadarData(health),\n          backgroundColor: \'rgba(26,111,181,0.15)\',\n          borderColor: \'#1a6fb5\',\n          pointBackgroundColor: \'#1a6fb5\',\n          borderWidth: 2,\n          pointRadius: 4,\n        },\n        {\n          label: \'Better for Earth 🌍\',\n          data: toRadarData(eco),\n          backgroundColor: \'rgba(45,122,79,0.15)\',\n          borderColor: \'#2d7a4f\',\n          pointBackgroundColor: \'#2d7a4f\',\n          borderWidth: 2,\n          pointRadius: 4,\n        },\n      ],\n    },\n    options: {\n      responsive: true,\n      plugins: {\n        legend: { position: \'bottom\', labels: { font: { size: 12 }, padding: 16 } },\n      },\n      scales: {\n        r: {\n          min: 0, max: 100,\n          ticks: { display: false },\n          pointLabels: { font: { size: 11 } },\n          grid: { color: \'#e5e7eb\' },\n          angleLines: { color: \'#e5e7eb\' },\n        },\n      },\n    },\n  });\n}\n\n/* ── Helpers ─────────────────────────────────────────────────────────────── */\nfunction clearResults() {\n  document.getElementById(\'results-section\').style.display = \'none\';\n  document.getElementById(\'emptyState\').style.display = \'block\';\n  document.getElementById(\'hero\').style.display = \'block\';\n  searchInput.value = \'\';\n  currentProductIdx = null;\n}\n\nfunction formatGrade(grade) {\n  const g = (grade || \'\').toLowerCase();\n  if (g === \'not-applicable\') return \'N/A\';\n  if (g === \'unknown\' || g === \'\') return \'?\';\n  if (g === \'a-plus\') return \'A+\';\n  return g.toUpperCase();\n}\n\nfunction gradeHtml(grade, prefix) {\n  const g = (grade || \'unknown\').toLowerCase().replace(\'+\', \'-plus\');\n  const label = formatGrade(grade);\n  return `<div class="grade-badge grade-${g}" title="${prefix}-Score ${label}">${label}</div>`;\n}\n\nfunction escHtml(s) {\n  if (!s) return \'\';\n  return String(s)\n    .replace(/&/g, \'&amp;\')\n    .replace(/</g, \'&lt;\')\n    .replace(/>/g, \'&gt;\')\n    .replace(/"/g, \'&quot;\');\n}\n\n// Also re-run recommendations when filters change\n[\'f_protein\', \'f_sugar\', \'f_organic\'].forEach(id => {\n  document.getElementById(id).addEventListener(\'change\', () => {\n    if (currentProductIdx !== null) loadRecommendations(currentProductIdx);\n  });\n});\ndocument.getElementById(\'allergenInput\').addEventListener(\'change\', () => {\n  if (currentProductIdx !== null) loadRecommendations(currentProductIdx);\n});\n</script>\n</body>\n</html>\n'
def find_csv():
    for p in [os.environ.get("BITREC_CSV",""),str(Path(__file__).parent/"openfoodfacts_short_30MB.csv"),str(Path(__file__).parent/"en.openfoodfacts.org.products.csv"),"openfoodfacts_short_30MB.csv","en.openfoodfacts.org.products.csv"]:
        if p and Path(p).is_file(): return p
    raise FileNotFoundError("CSV not found")
recommender=None
@asynccontextmanager
async def lifespan(app):
    global recommender
    df=load_data(find_csv()); recommender=Recommender(df); logger.info("BiteRec ready."); yield; recommender=None
app=FastAPI(title="BiteRec API",version="1.0.0",lifespan=lifespan)
app.add_middleware(CORSMiddleware,allow_origins=["*"],allow_methods=["*"],allow_headers=["*"])
@app.get("/",include_in_schema=False)
async def root(): return HTMLResponse(content=HTML_PAGE)
@app.get("/api/search")
async def search(q:str=Query(...,min_length=1)):
    if recommender is None: raise HTTPException(503,"Service not ready")
    r=recommender.search(q,top_k=12); return {"query":q,"results":r,"count":len(r)}
@app.get("/api/recommend/{product_idx}")
async def recommend(product_idx:int,health_weight:float=Query(0.7,ge=0.0,le=1.0),allergens:str=Query(""),high_protein:bool=False,low_sugar:bool=False,organic:bool=False):
    if recommender is None: raise HTTPException(503,"Service not ready")
    if product_idx<0 or product_idx>=len(recommender.df): raise HTTPException(404,"Not found")
    return recommender.recommend(product_idx,health_weight=health_weight,eco_weight=round(1-health_weight,3),allergen_input=allergens,filters={"high_protein":high_protein,"low_sugar":low_sugar,"organic":organic})
@app.get("/api/stats")
async def stats():
    if recommender is None: raise HTTPException(503,"Service not ready")
    df=recommender.df; return {"total_products":len(df),"categories":df["pnns_groups_1"].value_counts().to_dict(),"nutriscore_distribution":df["nutriscore_grade"].value_counts().to_dict(),"eco_distribution":df["environmental_score_grade"].value_counts().to_dict()}
if __name__=="__main__":
    import uvicorn; uvicorn.run("app:app",host="0.0.0.0",port=8000,reload=False)
